%% ========================================================================
%  Function: main_Figure_S3B
%
%  Description:
%      Main function to assemble positive and negative correlation subplots
%      into a single figure.
% =========================================================================
function main_Figure_S3B(outputDir)
    
    % Handle input arguments for output directory
    if nargin < 1
        outputDir = 'Figure';
    end

    % 1. Call sub-functions to generate plots
    fit_positive();
    
    % Capture the figure handle generated by the positive correlation function
    % (Assuming both functions plot into the same figure, or positive creates the figure)
    fig = gcf; 
    
    % 2. Call the negative correlation function (adds to the same figure)
    fit_negative();

    % 3. Save the combined figure
    % -------- Save Figure --------
    if ~isempty(outputDir)
        if ~exist(outputDir, 'dir')
            mkdir(outputDir);
        end
        outFile = fullfile(outputDir, 'Figure_S3B.png');
        exportgraphics(fig, outFile, 'Resolution', 300);
        fprintf('Saved: %s\n', outFile);
    end
end